      loadingProgress = 0; displayed = 0; fromVal = 0; toVal = 0;
      startTime = performance.now(); lastUpdate = startTime;
      root.classList.add('is-active');
      window.__bootSplashStarted = true;   // 供 index.html 兜底脚本判断 JS 是否已接管
